"""Kiểm thử trình duyệt: quản lý người dùng (mời qua email, mật khẩu tạm, đổi vai trò, khóa, xóa) và đặt/đổi mật khẩu.
Chạy:  npm run dev:fake   rồi   python3 test/ui-users.py"""
import asyncio, json, os, re, sys, urllib.request
from playwright.async_api import async_playwright
BASE = os.environ.get("BASE", "http://localhost:3100")
ok = True
def check(name, cond, extra=""):
    global ok
    print(("  ✓ " if cond else "  ✗ ") + name + ((" – " + str(extra)[:240]) if extra and not cond else "")); ok = ok and bool(cond)
def last_email():
    notify = re.search(r"Email/Telegram giả: (\S+)/last-email", open("/tmp/fake_site.log").read()).group(1)
    return json.loads(urllib.request.urlopen(notify + "/last-email").read())
async def login(pg, email, pw):
    await pg.goto(BASE + "/"); await pg.wait_for_selector('#login:not([hidden]),#app:not([hidden])')
    await pg.fill('#lgEmail', email); await pg.fill('#lgPass', pw); await pg.click('#lgBtn')
async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch(); errs = []
        A = await (await b.new_context(viewport={"width": 1300, "height": 900})).new_page(); A.on('pageerror', lambda e: errs.append(str(e)))
        await login(A, 'staff@netspace.vn', 'Mat-khau-1'); await A.wait_for_selector('#app:not([hidden])'); await A.wait_for_timeout(400)
        check("quản trị viên thấy mục Người dùng", await A.is_visible('#adminNav [data-tab="users"]') and "Quản trị viên" in await A.inner_text('#userName'))
        await A.click('#adminNav [data-tab="users"]'); await A.wait_for_function("usersState.list", timeout=10000)
        v = await A.inner_text('#view')
        check("danh sách có tài khoản; email ngoài chưa cấp quyền hiện 'Chưa có quyền'", "staff@netspace.vn" in v and "outsider@gmail.com" in v and "Chưa có quyền" in v and "Quản trị dự phòng" in v)
        check("không có nút Xóa ở chính mình", await A.evaluate("(()=>{const i=usersState.list.findIndex(u=>u.email===me.email);return !document.querySelector(`[data-act=uDel][data-i=\"${i}\"]`)})()"))
        print("Mời qua email")
        await A.fill('#uEmail', 'partner@gmail.com'); await A.fill('#uName', 'Chị Hoa'); await A.click('[data-act="uCreate"]')
        await A.wait_for_function("document.querySelector('#view').innerText.includes('Đã gửi email mời')", timeout=10000)
        await A.wait_for_function("!usersState.loading&&usersState.list.some(u=>u.email==='partner@gmail.com')", timeout=10000)
        check("danh sách hiện 'Đã mời, chưa đăng nhập'", "Đã mời, chưa đăng nhập" in await A.inner_text('#view'))
        link = re.search(r"(http://localhost:3100/#access_token=\S+)", last_email()["text"]).group(1)
        P = await (await b.new_context(viewport={"width": 390, "height": 844})).new_page(); P.on('pageerror', lambda e: errs.append(str(e)))
        await P.goto(link); await P.wait_for_selector('#pwForm:not([hidden])')
        check("link mời mở màn hình Đặt mật khẩu, xóa token khỏi thanh địa chỉ", "Đặt mật khẩu" in await P.inner_text('#pwTitle') and "access_token" not in P.url)
        await P.fill('#pwNew', 'ngan'); await P.fill('#pwNew2', 'ngan'); await P.click('#pwBtnGo')
        check("chặn mật khẩu yếu", "10 ký tự" in await P.inner_text('#pwErr'))
        await P.fill('#pwNew', 'ChiHoa-2026-ok'); await P.fill('#pwNew2', 'ChiHoa-2026-ok'); await P.click('#pwBtnGo'); await P.wait_for_selector('#app:not([hidden])', timeout=10000)
        check("đặt xong vào thẳng công cụ; nhân viên không thấy mục Người dùng", "partner@gmail.com" in await P.inner_text('#userChip') and not await P.is_visible('#adminNav [data-tab="users"]'))
        print("Mật khẩu tạm")
        await A.check('input[name=uMethod][value=password]'); await A.wait_for_selector('#uPw')
        await A.fill('#uEmail', 'ctv@abc.com'); await A.fill('#uName', 'Cộng tác viên'); await A.click('[data-act="uGen"]'); temp = await A.input_value('#uPw')
        check("tạo mật khẩu ngẫu nhiên hợp lệ", len(temp) >= 10 and re.search(r"\d", temp) and re.search(r"[A-Za-z]", temp), temp)
        await A.click('[data-act="uCreate"]'); await A.wait_for_function("document.querySelector('#view').innerText.includes('Đã tạo tài khoản ctv@abc.com')", timeout=10000)
        C = await (await b.new_context(viewport={"width": 1300, "height": 900})).new_page(); C.on('pageerror', lambda e: errs.append(str(e)))
        await login(C, 'ctv@abc.com', temp); await C.wait_for_selector('#pwForm:not([hidden])', timeout=10000)
        check("đăng nhập bằng mật khẩu tạm bị bắt đổi mật khẩu", "Đổi mật khẩu tạm" in await C.inner_text('#pwTitle') and await C.is_hidden('#app'))
        await C.fill('#pwNew', 'Ctv-Rieng-2026'); await C.fill('#pwNew2', 'Ctv-Rieng-2026'); await C.click('#pwBtnGo'); await C.wait_for_selector('#app:not([hidden])', timeout=10000)
        check("đổi xong vào được công cụ", "ctv@abc.com" in await C.inner_text('#userChip'))
        await C.wait_for_function("!document.querySelector('#pwBtnGo').disabled")
        await C.click('#pwBtn'); await C.wait_for_selector('#pwForm:not([hidden])'); await C.wait_for_timeout(100)
        check("nút Đổi mật khẩu yêu cầu mật khẩu hiện tại, có nút Hủy", await C.is_visible('#pwCur') and await C.is_visible('#pwCancel'))
        await C.fill('#pwCur', 'sai-mat-khau-1'); await C.fill('#pwNew', 'Ctv-Moi-2026x'); await C.fill('#pwNew2', 'Ctv-Moi-2026x'); await C.click('#pwBtnGo')
        await C.wait_for_function("document.querySelector('#pwErr').textContent.length>0||!document.querySelector('#app').hidden", timeout=10000)
        check("sai mật khẩu hiện tại bị từ chối", "chưa đúng" in await C.inner_text('#pwErr'), await C.inner_text('#pwErr'))
        await C.fill('#pwCur', 'Ctv-Rieng-2026'); await C.click('#pwBtnGo'); await C.wait_for_selector('#app:not([hidden])', timeout=10000)
        check("đổi mật khẩu thành công, quay lại công cụ", True)
        print("Sửa vai trò, khóa, xóa")
        await A.click('[data-act="usersReload"]'); await A.wait_for_function("!usersState.loading")
        i = await A.evaluate("usersState.list.findIndex(u=>u.email==='ctv@abc.com')")
        await A.click(f'[data-act="uOpen"][data-i="{i}"]'); await A.select_option(f'#ur_{i}', 'admin'); await A.click(f'[data-act="uSave"][data-i="{i}"]'); await A.wait_for_timeout(600)
        check("đổi vai trò thành Quản trị viên", await A.evaluate("usersState.list.find(u=>u.email==='ctv@abc.com').role") == 'admin')
        await C.reload(); await C.wait_for_selector('#app:not([hidden])'); await C.wait_for_timeout(400)
        check("người được nâng quyền thấy mục Người dùng", await C.is_visible('#adminNav [data-tab="users"]'))
        j = await A.evaluate("usersState.list.findIndex(u=>u.email==='partner@gmail.com')")
        if await A.evaluate(f"usersState.open!==usersState.list[{j}].email"): await A.click(f'[data-act="uOpen"][data-i="{j}"]')
        await A.click(f'[data-act="uToggle"][data-i="{j}"]'); await A.wait_for_timeout(600)
        check("khóa tài khoản", "Đã khóa" in await A.inner_text('#view'))
        await P.reload(); await P.wait_for_selector('#login:not([hidden])', timeout=10000)
        check("tài khoản bị khóa bị đẩy ra màn hình đăng nhập", await P.is_visible('#lgForm'))
        j = await A.evaluate("usersState.list.findIndex(u=>u.email==='partner@gmail.com')")
        await A.click(f'[data-act="uDel"][data-i="{j}"]'); await A.wait_for_timeout(150)
        check("bấm Xóa lần 1 chỉ hỏi xác nhận", await A.evaluate("usersState.list.some(u=>u.email==='partner@gmail.com')"))
        await A.click(f'[data-act="uDel"][data-i="{j}"]'); await A.wait_for_timeout(700)
        check("bấm lần 2 xóa tài khoản", not await A.evaluate("usersState.list.some(u=>u.email==='partner@gmail.com')") and "Đã xóa tài khoản" in await A.inner_text('#view'))
        M = await (await b.new_context(viewport={"width": 390, "height": 844})).new_page()
        await login(M, 'staff@netspace.vn', 'Mat-khau-1'); await M.wait_for_selector('#app:not([hidden])'); await M.evaluate("tab='users';loadUsers();renderAll()"); await M.wait_for_function("usersState.list"); await M.wait_for_timeout(300)
        check("trang Người dùng trên điện thoại không tràn ngang", not await M.evaluate("document.documentElement.scrollWidth>document.documentElement.clientWidth+1"))
        await M.screenshot(path='/tmp/users_m.png', full_page=True); await A.screenshot(path='/tmp/users_d.png', full_page=True)
        check("không có lỗi JavaScript", not errs, errs)
        await b.close()
    print("\nTẤT CẢ ĐẠT" if ok else "\nCÓ LỖI"); sys.exit(0 if ok else 1)
asyncio.run(main())
